import {interiorAt} from './interior-layout.js';
import {decodeActivity} from './activity-state.js';
import {createActivityReactions} from './activity-reactions.js';
import * as T from './vendor/three.module.js';
import {createCompanion} from './companion.js';
import {moveOnGround} from './movement.js';
import {clearSegment,findPath} from './navigation.js';
import {surfaceHeight} from './world-layout.js';
export function createVisitors(scene){
 const peers=new Map(),container=document.querySelector('#visitor-labels'),screen=new T.Vector3();
 function remove(id,p){scene.remove(p.pet.group);p.reactions.dispose?.();p.label.remove();const geometries=new Set(),materials=new Set();p.pet.group.traverse(o=>{if(o.geometry)geometries.add(o.geometry);if(o.material)for(const m of Array.isArray(o.material)?o.material:[o.material])materials.add(m);});geometries.forEach(g=>g.dispose());materials.forEach(m=>{if(!m.userData.shared)m.dispose();});peers.delete(id);}
 window.addEventListener('lab:visitors',e=>{const ids=new Set(e.detail.map(p=>p.id));for(const [id,p]of peers)if(!ids.has(id))remove(id,p);for(const state of e.detail){let peer=peers.get(state.id);if(!peer){const pet=createCompanion({detail:'remote'}),label=document.createElement('span');label.className='visitor-label';const name=document.createElement('b'),bubble=document.createElement('div');name.textContent=state.name;bubble.className='speech-bubble';label.append(name,bubble);container.append(label);pet.group.position.set(state.x,state.y??.95,state.z);scene.add(pet.group);peer={pet,label,state,route:[],fx:{id:state.id},reactions:createActivityReactions(scene)};peers.set(state.id,peer);}const current=peer.pet.group.position;peer.route=!state.mode&&Math.hypot(current.x-state.x,current.z-state.z)<12&&!clearSegment(current,state)?findPath(current,state):[];peer.state=state;peer.label.querySelector('b').textContent=state.name;const bubble=peer.label.querySelector('.speech-bubble');bubble.textContent=state.chat||'';bubble.hidden=!state.chat||Date.now()-state.chatAt>6500;peer.pet.customize({fur:state.color,accessory:state.accessory});peer.pet.equip(['ski','lift','summit'].includes(state.mode)?(peer.pet.gear==='board'?'board':'ski'):state.mode==='sled'?'sled':state.mode==='skate'?'skates':['bath','sauna','lie','tea','carousel','ferris','teacups','bumper'].includes(state.mode)?'none':peer.pet.gear);}});
 function rectFor(label){const r=label.getBoundingClientRect(),b=label.querySelector('.speech-bubble'),q=b&&!b.hidden?b.getBoundingClientRect():r;return{left:Math.min(r.left,q.left),right:Math.max(r.right,q.right),top:Math.min(r.top,q.top),bottom:Math.max(r.bottom,q.bottom)};}
 return{effectStates(){return [...peers.values()].filter(p=>p.pet.group.visible).map(p=>p.fx);},update(dt,time,camera){const own=document.querySelector('#self-label'),occupied=own&&!own.hidden?[rectFor(own)]:[];for(const p of peers.values()){const s=p.state,g=p.pet.group,visible=(interiorAt(s.x,s.z)?.id||null)===(window.labInterior||null);g.visible=visible;if(!visible){p.label.hidden=true;continue;}const oldX=g.position.x,oldZ=g.position.z,d=Math.hypot(oldX-s.x,oldZ-s.z),blend=1-Math.exp(-dt*5);
  if(d>12){g.position.set(s.x,s.y??.95,s.z);p.route=[];}
  else if(!s.mode){while(p.route.length&&Math.hypot(g.position.x-p.route[0].x,g.position.z-p.route[0].z)<.12)p.route.shift();const target=p.route[0]||s,step=moveOnGround(g.position,{x:(target.x-g.position.x)*blend/Math.max(dt,.001),z:(target.z-g.position.z)*blend/Math.max(dt,.001)},dt);g.position.x=step.x;g.position.z=step.z;g.position.y=Math.max(surfaceHeight(step.x,step.z)+.86,g.position.y+((s.y??.95)-g.position.y)*blend);}
  else g.position.lerp(new T.Vector3(s.x,s.y??.95,s.z),blend);
  Object.assign(p.fx,{x:g.position.x,y:g.position.y,z:g.position.z,yaw:g.rotation.y,mode:s.mode,accessory:s.accessory,emote:s.gesture,speed:d>12?0:Math.min(40,Math.hypot(g.position.x-oldX,g.position.z-oldZ)/Math.max(dt,.001))});
  const turn=Math.atan2(Math.sin(s.yaw-g.rotation.y),Math.cos(s.yaw-g.rotation.y));g.rotation.y+=turn*blend;p.pet.pose({room:interiorAt(s.x,s.z)?.id,mode:s.mode,...decodeActivity(s.gesture||''),walking:d>.15&&(!s.mode||s.mode==='summit'),phase:time*7,time});p.reactions.update({...decodeActivity(s.gesture||''),mode:s.mode,x:g.position.x,y:g.position.y,z:g.position.z,yaw:g.rotation.y,time,dt,still:document.body.classList.contains('still')});screen.copy(g.position).add(new T.Vector3(0,p.pet.nameHeight,0)).project(camera);p.label.hidden=screen.z>1||screen.z< -1||window.isVisitorBlocked?.(s.id);const bubble=p.label.querySelector('.speech-bubble'),remaining=6500-(Date.now()-s.chatAt);bubble.hidden=!s.chat||remaining<=0;bubble.style.opacity=String(Math.max(0,Math.min(1,remaining/700)));
  const x=(screen.x*.5+.5)*innerWidth;let y=(-screen.y*.5+.5)*innerHeight-6;p.label.style.transform=`translate(${x}px,${y}px) translate(-50%,-100%)`;if(!p.label.hidden){let rect=rectFor(p.label);for(const avoid of occupied){if(rect.right>avoid.left-5&&rect.left<avoid.right+5&&rect.bottom>avoid.top-5&&rect.top<avoid.bottom+5){const dy=rect.bottom-avoid.top+7;y-=dy;rect.top-=dy;rect.bottom-=dy;}}p.label.style.transform=`translate(${x}px,${y}px) translate(-50%,-100%)`;occupied.push(rect);}
 }}};
}
